import Config from "../../configManager/configManager";
import { extractDetailsFromCslp, isValidCslp } from "../../cslp";

/**
 * Returns the redirection URL for the Visual builder.
 * @returns {URL} The redirection URL.
 */
export default function getVisualBuilderRedirectionUrl(): URL {
    const { stackDetails, clientUrlParams } = Config.get();
    const { branch, apiKey, environment, locale } = stackDetails;
    const { url: appUrl } = clientUrlParams;

    const searchParams = new URLSearchParams();
    if (branch) {
        searchParams.set("branch", branch);
    }
    if (environment) {
        searchParams.set("environment", environment);
    }

    searchParams.set("target-url", window.location.href);

    // get the locale from the data cslp attribute
    const elementWithDataCslp = document.querySelector(`[data-cslp]`);
    let localeToUse = locale;

    if (elementWithDataCslp) {
        const cslpData = elementWithDataCslp.getAttribute("data-cslp");
        if (isValidCslp(cslpData)) {
            const { locale: cslpLocale } = extractDetailsFromCslp(cslpData);
            localeToUse = cslpLocale;
        }
    }

    if (localeToUse) {
        searchParams.set("locale", localeToUse);
    }

    // Resolve page entry context via four-layer priority chain:
    // 1. setPageContext() call  →  explicit programmatic (CSR / useEffect)
    // 2. window.__CS_PAGE_CONTEXT__  →  inline <script> (SSR templates)
    // 3. Meta tags  →  framework head APIs (Next.js <Head>, Nuxt useHead)
    // 4. No context  →  VB falls back to legacy entry.url suffix search
    const pageContext = Config.get().pageContext;
    const windowContext = (window as any).__CS_PAGE_CONTEXT__;

    const entryUid =
        pageContext?.entryUid ??
        windowContext?.entryUid ??
        document
            .querySelector('meta[name="contentstack:entry-uid"]')
            ?.getAttribute("content");

    const contentTypeUid =
        pageContext?.contentTypeUid ??
        windowContext?.contentTypeUid ??
        document
            .querySelector('meta[name="contentstack:content-type-uid"]')
            ?.getAttribute("content");

    if (entryUid) {
        searchParams.set("entry_uid", entryUid);
    }
    if (contentTypeUid) {
        searchParams.set("content_type_uid", contentTypeUid);
    }

    const completeURL = new URL(
        `/#!/stack/${apiKey}/visual-editor?${searchParams.toString()}`,
        appUrl
    );
    return completeURL;
}
